import java.util.*;

class StockPrice {
    private final Map<Integer, Integer> timestampToPrice = new HashMap<>();
    private final TreeMap<Integer, Integer> priceCounts = new TreeMap<>();
    private int latestTimestamp = 0;

    public StockPrice() {
    }

    public void update(int timestamp, int price) {
        Integer oldPrice = timestampToPrice.put(timestamp, price);
        if (oldPrice != null) {
            int count = priceCounts.get(oldPrice);
            if (count == 1) {
                priceCounts.remove(oldPrice);
            } else {
                priceCounts.put(oldPrice, count - 1);
            }
        }
        priceCounts.merge(price, 1, Integer::sum);
        latestTimestamp = Math.max(latestTimestamp, timestamp);
    }

    public int current() {
        return timestampToPrice.get(latestTimestamp);
    }

    public int maximum() {
        return priceCounts.lastKey();
    }

    public int minimum() {
        return priceCounts.firstKey();
    }
}

import java.util.*;

class StockPrice {
    private final Map<Integer, Integer> timestampToPrice = new HashMap<>();
    private final PriorityQueue<int[]> maxHeap = new PriorityQueue<>((a, b) -> {
        if (a[0] != b[0]) return Integer.compare(b[0], a[0]);
        return Integer.compare(b[1], a[1]);
    });
    private final PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> {
        if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
        return Integer.compare(a[1], b[1]);
    });
    private int latestTimestamp = 0;

    public StockPrice() {
    }

    public void update(int timestamp, int price) {
        timestampToPrice.put(timestamp, price);
        maxHeap.offer(new int[] {price, timestamp});
        minHeap.offer(new int[] {price, timestamp});
        latestTimestamp = Math.max(latestTimestamp, timestamp);
    }

    public int current() {
        return timestampToPrice.get(latestTimestamp);
    }

    public int maximum() {
        while (true) {
            int[] top = maxHeap.peek();
            if (timestampToPrice.get(top[1]) == top[0]) {
                return top[0];
            }
            maxHeap.poll();
        }
    }

    public int minimum() {
        while (true) {
            int[] top = minHeap.peek();
            if (timestampToPrice.get(top[1]) == top[0]) {
                return top[0];
            }
            minHeap.poll();
        }
    }
}

import java.util.*;

class StockPrice {
    private static class Record {
        final int timestamp;
        final int price;

        Record(int timestamp, int price) {
            this.timestamp = timestamp;
            this.price = price;
        }
    }

    private final Map<Integer, Record> byTimestamp = new HashMap<>();
    private final TreeSet<Record> byPrice = new TreeSet<>((a, b) -> {
        if (a.price != b.price) return Integer.compare(a.price, b.price);
        return Integer.compare(a.timestamp, b.timestamp);
    });
    private int latestTimestamp = 0;

    public StockPrice() {
    }

    public void update(int timestamp, int price) {
        Record oldRecord = byTimestamp.get(timestamp);
        if (oldRecord != null) {
            byPrice.remove(oldRecord);
        }
        Record newRecord = new Record(timestamp, price);
        byTimestamp.put(timestamp, newRecord);
        byPrice.add(newRecord);
        latestTimestamp = Math.max(latestTimestamp, timestamp);
    }

    public int current() {
        return byTimestamp.get(latestTimestamp).price;
    }

    public int maximum() {
        return byPrice.last().price;
    }

    public int minimum() {
        return byPrice.first().price;
    }
}

import java.util.*;

class StockPrice {
    private static final int MIN_PRICE = 1;
    private static final int MAX_PRICE = 1_000_000_000;

    private static class Node {
        int count;
        Node left;
        Node right;
    }

    private final Map<Integer, Integer> timestampToPrice = new HashMap<>();
    private final Node root = new Node();
    private int latestTimestamp = 0;

    public StockPrice() {
    }

    public void update(int timestamp, int price) {
        Integer oldPrice = timestampToPrice.put(timestamp, price);
        if (oldPrice != null) {
            add(root, MIN_PRICE, MAX_PRICE, oldPrice, -1);
        }
        add(root, MIN_PRICE, MAX_PRICE, price, 1);
        latestTimestamp = Math.max(latestTimestamp, timestamp);
    }

    public int current() {
        return timestampToPrice.get(latestTimestamp);
    }

    public int maximum() {
        return findMax(root, MIN_PRICE, MAX_PRICE);
    }

    public int minimum() {
        return findMin(root, MIN_PRICE, MAX_PRICE);
    }

    private void add(Node node, int left, int right, int price, int delta) {
        node.count += delta;
        if (left == right) {
            return;
        }
        int mid = left + (right - left) / 2;
        if (price <= mid) {
            if (node.left == null) {
                node.left = new Node();
            }
            add(node.left, left, mid, price, delta);
        } else {
            if (node.right == null) {
                node.right = new Node();
            }
            add(node.right, mid + 1, right, price, delta);
        }
    }

    private int findMin(Node node, int left, int right) {
        if (left == right) {
            return left;
        }
        int mid = left + (right - left) / 2;
        if (node.left != null && node.left.count > 0) {
            return findMin(node.left, left, mid);
        }
        return findMin(node.right, mid + 1, right);
    }

    private int findMax(Node node, int left, int right) {
        if (left == right) {
            return left;
        }
        int mid = left + (right - left) / 2;
        if (node.right != null && node.right.count > 0) {
            return findMax(node.right, mid + 1, right);
        }
        return findMax(node.left, left, mid);
    }
}

import java.util.*;

class StockPrice {
    private final Map<Integer, Integer> timestampToPrice = new HashMap<>();
    private final Map<Integer, Integer> priceCounts = new HashMap<>();
    private int latestTimestamp = 0;
    private int minPrice = Integer.MAX_VALUE;
    private int maxPrice = Integer.MIN_VALUE;

    public StockPrice() {
    }

    public void update(int timestamp, int price) {
        Integer oldPrice = timestampToPrice.put(timestamp, price);
        boolean removedExtreme = false;
        if (oldPrice != null) {
            int count = priceCounts.get(oldPrice) - 1;
            if (count == 0) {
                priceCounts.remove(oldPrice);
                if (oldPrice == minPrice || oldPrice == maxPrice) {
                    removedExtreme = true;
                }
            } else {
                priceCounts.put(oldPrice, count);
            }
        }

        priceCounts.merge(price, 1, Integer::sum);
        latestTimestamp = Math.max(latestTimestamp, timestamp);

        if (priceCounts.size() == 1) {
            minPrice = price;
            maxPrice = price;
        } else if (removedExtreme) {
            rebuildExtremes();
        } else {
            minPrice = Math.min(minPrice, price);
            maxPrice = Math.max(maxPrice, price);
        }
    }

    public int current() {
        return timestampToPrice.get(latestTimestamp);
    }

    public int maximum() {
        return maxPrice;
    }

    public int minimum() {
        return minPrice;
    }

    private void rebuildExtremes() {
        minPrice = Integer.MAX_VALUE;
        maxPrice = Integer.MIN_VALUE;
        for (int price : priceCounts.keySet()) {
            minPrice = Math.min(minPrice, price);
            maxPrice = Math.max(maxPrice, price);
        }
    }
}
